\documentclass[sloppy,11pt]{article}

\usepackage{graphicx}
\usepackage{booktabs}
\usepackage{amsmath}
\usepackage{url}

\title{Transcriptional Metabolic States in Meningioma Single-Cell RNA-seq Data}
\author{Analysis based on Choudhury et al. 2022 (3CA:20773)}
\date{}

\begin{document}

\sloppy

\maketitle

\begin{abstract}
This study investigates whether transcriptional metabolic states can be identified as distinct clusters in single-cell RNA-seq data from meningioma samples. We analyze 58,843 cells from the Choudhury et al. 2022 dataset using Reactome metabolism pathway genes (R-HSA-1430728, release 97).
\end{abstract}

\section{Methods}

\subsection{Data Sources}
The analysis uses the Choudhury et al. 2022 meningioma single-cell RNA-seq dataset (3CA:20773), published in Nature Genetics \url{https://www.nature.com/articles/s41588-022-01061-8}. The dataset contains 58,843 cells and 33,538 genes from 10 samples.

\subsection{Normalization}
Expression data was normalized using per-cell library size scaling to 10,000 counts, followed by log1p transformation:
\begin{equation}
\label{eq:log1p}
\log_2\left(\frac{x + 1}{10000}\right)
\end{equation}
where $x$ represents the raw UMI count for a given gene in a given cell.

\subsection{Feature Selection}
Reactome metabolism pathway genes (R-HSA-1430728, release 97) were retrieved from the Reactome database. After filtering for prevalence (present in $\geq 20$ cells) and excluding mitochondrial genes, 1,984 metabolic genes remained for analysis.

\subsection{Clustering}
Leiden clustering was performed on the PCA-reduced space using 10x Genomics 3' gene expression data. Clustering was evaluated across multiple resolutions (0.4, 0.8, 1.2) and seeds (0, 17, 42, 73, 101) to assess stability.

\section{Results}

\subsection{Global Clustering Analysis}
Using only the 1,984 metabolic genes, we identified 15 clusters across the 58,843 cells at resolution 0.4. The clustering solution achieved a silhouette score of 0.229, with cluster sizes ranging from 1,002 to 8,985 cells.

\begin{figure}[ht]
\centering
\includegraphics[width=\textwidth]{../figures/metabolic_umap.pdf}
\caption{UMAP visualization of cells clustered using only Reactome metabolism pathway genes (1,984 genes). Each color represents a Leiden cluster. Cluster sizes range from 1,002 to 8,985 cells.}
\label{fig:metabolic_umap}
\end{figure}

\subsection{Clustering Diagnostics}
Clustering quality was assessed using multiple metrics: silhouette score (0.229), Calinski-Harabasz index (7,177), and Davies-Bouldin index (1.51). Stability was evaluated across 5 random seeds and 3 resolutions, with mean pairwise ARI of 0.980 and minimum pairwise ARI of 0.973.

\begin{figure}[ht]
\centering
\includegraphics[width=\textwidth]{../figures/clustering_diagnostics.pdf}
\caption{Clustering diagnostics showing silhouette scores across seeds and resolutions. The selected resolution (0.4) achieves the highest median silhouette score with stable cluster assignments across seeds.}
\label{fig:clustering_diagnostics}
\end{figure}

\subsection{Random Control Comparison}
To assess whether metabolic genes provide meaningful clustering, we compared against 19 size-matched random controls using K-means clustering with 15 clusters. No random control achieved a silhouette score $\geq$ 0.229 (the metabolic clustering score), with 0 out of 19 random controls exceeding or equal to the metabolic clustering.

\subsection{Confounder Assessment}
We assessed potential confounding by patient, sample, source, cell type, cell subtype, cell cycle phase, and complexity. The NMI between clusters and categorical confounders ranged from 0.197 (source) to 0.658 (cell subtype), indicating moderate associations.

\subsection{Within-Replicate Sensitivity}
Assessing cluster stability within biological replicates (patients), we found the weakest replicate (patient 3, 3,287 cells) had a global-vs-within ARI of 0.106. Across 6 assessable replicates, the global-vs-within ARI ranged from 0.106 to 0.813.

\section{Discussion}

\subsection{Can Metabolic Genes Form Distinct Clusters?}
The analysis demonstrates that metabolic genes alone can form 15 distinct clusters in the single-cell RNA-seq dataset. However, the silhouette score (0.229) is relatively low, and the clustering shows strong stability across seeds (mean pairwise ARI = 0.980), suggesting the clusters may reflect technical or batch effects rather than biological metabolic states.

\subsection{Cell-Type Associations}
The clustering shows moderate associations with cell type (NMI = 0.507) and cell subtype (NMI = 0.658), suggesting that the observed clusters may partially reflect cell-type composition rather than distinct metabolic states within cell types.

\subsection{Conclusion}
While metabolic genes can computationally separate cells into 15 clusters, the inconclusive nature of the silhouette score and moderate confounder associations suggests these clusters should not be interpreted as distinct biological metabolic states. Further validation with orthogonal methods and larger sample sizes would be needed to establish discrete metabolic states.

\section{References}

\begin{thebibliography}{99}

\bibitem{Choudhury2022}
Abrar Choudhury, Stephen T. Magill, Charlotte D. Eaton, et al.
``Meningioma DNA methylation groups identify biological drivers and therapeutic vulnerabilities.''
\textit{Nature Genetics} 54(5): 649--659, 2022.
\url{https://doi.org/10.1038/s41588-022-01061-8}

\bibitem{Reactome2024}
The Reactome Database.
``Reactome Pathway Database.''
Reactome, 2024. \url{https://reactome.org}

\end{thebibliography}

\end{document}

